def mod_inverse(a, m):
    """Return a modular inverse of a modulo m if it exists, else -1."""
    while a < 0:
        a += m
    g, x, y = 1, 0, 1
    while a != 0:
        q, a, g, x, y = g // a, g % a, a, x - q * x, y - q * y
    if g != 1:
        return -1
    while x < 0:
        x += m
    return x
