def sort_case_insensitive_then_sensitive(words):
    words = sorted([w for w in words], key=lambda w: w.lower())
    equals = []
    for i in range(len(words) - 1):
        if words[i].lower() == words[i + 1].lower():
            equals.append(words[i])
    equals.append(words[-1])
    for i in range(len(equals) - 1):
        j = i + 1
        while j <= len(equals) - 1 and equals[j].lower() == equals[j - 1].lower():
            j += 1
        if j <= len(equals) - 1:
            equals[i:j] = sorted(equals[i:j])
    result = []
    for i in range(len(words)):
        if i == 0 or words[i - 1].lower() != words[i].lower():
            when, at = 0, i
            while at < len(equals) and equals[when] != words[i]:
                if equals[when].lower() == words[i].lower():
                    at += 1
                else:
                    when += 1
            result.append(equals[when])
    return result
