def chunk_into_n_parts(lst, n):
    if n == 0:
        raise ValueError("n must be at least 1")
    size, r = divmod(len(lst), n)
    parts = []
    for i in range(n):
        if i < r:
            parts.append(lst[i * (size + 1) : (i + 1) * (size + 1)])
