def zeckendorf_length(n):
    if n == 0:
        return 0
    # List of Fibonacci numbers up to n.
    fibs = [1, 2]
    while fibs[-1] < n:
        fibs.append(fibs[-1] + fibs[-2])
    # Greedy selection, subtracting only the largest Fibonacci number below n.
    terms = 0
    while n > 0:
        largest = fibs[-1]  # last index is the largest at most n
        if largest <= n:
            n -= largest
            terms += 1
            fibs.pop()
        else:
            fibs.pop()
    return terms

```

