def find_repeated_substrings_of_length(s, k):
    if k < 1 or k > len(s):
        return []
    seen = set()
    first_seen = {}
    for i in range(len(s) - k + 1):
        t = s[i:i + k]
        if t in first_seen:
            continue
        elif t in seen:
            first_seen[t] = True
            seen.remove(t)  # so first occurrence is reported first
        else:
            seen.add(t)
    return sorted(seen, key=s.index)
