def caesar_shift(s, shift):
    shift %= 26    # reduce shift to a value between 0 and 25
    result = []
    for c in s:
        if c.isalpha():
            base = ord('A') if c.isupper() else ord('a')
            c = chr((ord(c) - base + shift) % 26 + base)  # wrap around and restore case
        result.append(c)
    return ''.join(result)
